method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0
    ensures |result| == |numbers|
    ensures forall i :: 0 <= i < |result| ==> result[i] == Max(Head(numbers, i + 1))
{
    var maxSoFar := numbers[0];
    result := [];

    // Iterate through the input sequence
    var i := 0;
    while i < |numbers|
        invariant 0 <= i <= |numbers|
        invariant |result| == i
        invariant forall j :: 0 <= j < i ==> result[j] == Max(Head(numbers, j + 1))
    {
        // Update the maximum value found so far
        if numbers[i] > maxSoFar {
            maxSoFar := numbers[i];
        }

        // Append the current maximum to the result
        result := result + [maxSoFar];

        // Move to the next index
        i := i + 1;
    }
}

